function SummaryCard({ title, value }: { title: string; value: string }) {
  return (
    <div className="border rounded-2xl bg-white p-4">
      <p className="text-sm text-gray-500">{title}</p>
      <p className="text-2xl font-bold mt-1">{value}</p>
    </div>
