}
function toYmd(d: Date) {
  const y = d.getFullYear(); const m = String(d.getMonth() + 1).padStart(2, "0"); const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}
const krw = (n: number) => n.toLocaleString("ko-KR") + "원";
const nf = (n: number) => n.toLocaleString("ko-KR");

/** 데모 데이터 생성기: price 포함 */
function mockTop(from: string, to: string, groupBy: GroupBy): ApiResp {
  const products = [
    { name: "SYND 데몬 덕다운 경량 후드 패딩", price: 120000, variants: [{ name: "Light Blue / FREE", price: 120000 }, { name: "Black / FREE", price: 120000 }] },
    { name: "러플 스커트", price: 39000, variants: [{ name: "Ivory / S", price: 39000 }, { name: "Ivory / M", price: 39000 }] },
    { name: "플로럴 원피스", price: 54000, variants: [{ name: "Green / S", price: 54000 }, { name: "Green / M", price: 54000 }] },
    { name: "새틴 블라우스", price: 32000, variants: [{ name: "Pink / M", price: 32000 }] },
    { name: "니트 가디건", price: 45000, variants: [{ name: "Black / Free", price: 45000 }] },
  ];

  const items: TopItem[] = [];
  products.forEach((p, pi) => {
    const baseQty = Math.max(3, 40 - pi * 7 + rand(-6, 10));
    if (groupBy === "product") {
      const qty = baseQty;
      const price = p.price;
      items.push({
        id: `P-${pi}`,
        name: p.name,
        price,
        qty,
        revenue: price * qty,
      });
    } else {
      p.variants.forEach((v, vi) => {
        const qty = Math.max(1, Math.round(baseQty * (0.6 + vi * 0.5) + rand(-3, 3)));
        const price = v.price;
        items.push({
          id: `V-${pi}-${vi}`,
          name: `${p.name} | ${v.name}`,
          price,
          qty,
          revenue: price * qty,
        });
      });
    }
  });

  return {
    items,
    summary: {
      totalQty: items.reduce((s, v) => s + v.qty, 0),
      totalRevenue: items.reduce((s, v) => s + v.revenue, 0),
    },
  };
}
function rand(min: number, max: number) { return Math.floor(Math.random() * (max - min + 1)) + min; }
